pous.declaration:
FUNCTION_BLOCK Elevator
VAR_INPUT
    targetFloor : INT;
    floorSensor1 : BOOL;
    floorSensor2 : BOOL;
    floorSensor3 : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    doorOpen : BOOL;
END_VAR
VAR
    current : INT := 1;
    stage : INT := 0;
    doorTon : TON;
END_VAR

pous.implementation:
motorUp := FALSE;
motorDown := FALSE;
doorOpen := FALSE;
CASE stage OF
0:
    IF floorSensor1 THEN current := 1;
    ELSIF floorSensor2 THEN current := 2;
    ELSIF floorSensor3 THEN current := 3;
    END_IF
    IF targetFloor <> current THEN
        IF targetFloor > current THEN
            motorUp := TRUE;
        ELSE
            motorDown := TRUE;
        END_IF
        IF (targetFloor = 1 AND floorSensor1) OR (targetFloor = 2 AND floorSensor2)
            OR (targetFloor = 3 AND floorSensor3) THEN
            stage := 1;
        END_IF
    END_IF
1:
    doorOpen := TRUE;
    doorTon(IN := TRUE, PT := T#3s);
    IF doorTon.Q THEN
        stage := 0;
    END_IF
END_CASE
